toolArgs.file_text:
@namespace sv_f94c3d13b9634cbc917ee8f5b42f04e1.Components.Pages.Settings
@using sv_f94c3d13b9634cbc917ee8f5b42f04e1.Services

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <div class="text-center p-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h5>Theme</h5>
                    <div class="btn-group" role="group">
                        @foreach (var theme in _themes)
                        {
                            <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        @foreach (var size in _fontSizes)
                        {
                            <input type="radio" class="btn-check" name="fontSize" id="@($"fs-{size}")"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="btn btn-outline-secondary" for="@($"fs-{size}")">@size</label>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang.Key">@lang.Value</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                    <small class="text-muted">Reduces spacing and padding throughout the interface.</small>
                </div>

                @if (!string.IsNullOrEmpty(_message))
                {
                    <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                        @_message
                        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                    </div>
                }

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is how your content will appear with the selected settings.
                        </p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <span class="badge bg-secondary ms-2">Badge</span>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("bg-dark text-light");
        if (_compactMode) classes.Add("p-2");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var styles = new List<string>();
        if (_theme == "Dark")
            styles.Add("background-color: #1a1a2e; color: #eaeaea;");
        else
            styles.Add("background-color: #ffffff; color: #212529;");

        if (_compactMode)
            styles.Add("padding: 0.5rem;");

        return string.Join(" ", styles);
    }

    private string GetPreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

